def transform(grid):
    g=[row[:] for row in grid]
    bg=max(set(v for row in g for v in row), key=sum(row.count(v) for row in g))
    # A horizontal five-cell pattern on the background encodes the stamp;
    # sparse marker cells of the same task color are stamped at their locations.
    stamps=[]
    for r,row in enumerate(g):
        for c in range(len(row)-4):
            vals=row[c:c+5]
            if bg not in vals and len(set(vals))>1:
                stamps.append((r,c,vals[:]))
    if not stamps: return g
    # markers are the isolated non-background color distinct from stamp colors
    stampcolors={v for _,_,vals in stamps for v in vals}
    marks=[]
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v!=bg and v not in stampcolors:
                marks.append((r,c))
    # remove stamp's non-background cells from marker consideration
    for r,c,vals in stamps:
        for k,v in enumerate(vals):
            if v!=bg: g[r][c+k]=v
    motif=stamps[0][2]
    for r,c in marks:
        for k,v in enumerate(motif):
            x=c+k-2
            if 0<=x<len(g[0]): g[r][x]=v
    return g
